fn remove_duplicates(nums: &Vec<i32>) -> usize {
    // Handle the case of an empty array
    if nums.is_empty() {
        return 0;
    }

    // Initialize the count of distinct values
    let mut count = 1; // Start with 1 for the first unique element

    // Iterate through the array starting from the second element
    for i in 1..nums.len() {
        // If the current element is different from the previous one, it's unique
        if nums[i] != nums[i - 1] {
            count += 1; // Increment the count of unique elements
        }
    }

    // Return the count of distinct values
    count
}